-- Synthetic Discord Pulse v0.3.0 schema, copied structurally from dashboard/pulse.py.
-- No user watchlist or payloads. Data are generated by test_migrate.py.
CREATE TABLE servers (
    id TEXT PRIMARY KEY, code TEXT NOT NULL, payload TEXT NOT NULL,
    next_due REAL NOT NULL DEFAULT 0, widget_due REAL NOT NULL DEFAULT 0,
    widget TEXT, widget_state TEXT NOT NULL DEFAULT 'unchecked',
    error TEXT, failures INTEGER NOT NULL DEFAULT 0);
CREATE TABLE snapshots (
    guild TEXT NOT NULL, ts REAL NOT NULL, payload TEXT NOT NULL,
    PRIMARY KEY(guild, ts));
CREATE TABLE gates (key TEXT PRIMARY KEY, until_ts REAL NOT NULL);
